<?php if($channel==='sms'): ?><section class="comm-card"><div class="comm-head"><div><h2>Import your phone numbers</h2><p class="muted">Download the sample, fill in your contacts, then upload the completed file.</p></div><a class="btn" href="<?= base_url('communications/sample/sms'); ?>" download="martpoint-sms-contacts-sample.csv">Download SMS import sample</a></div><ol><li>Open the CSV in Excel, Google Sheets or another spreadsheet app.</li><li>Keep the <b>name</b> and <b>phone</b> headings. Replace the example rows with your contacts, one phone number per row. Names are optional.</li><li>Format the phone column as <b>Text</b>. Use Nigerian mobile numbers such as <b>2348012345678</b> or <b>08012345678</b>.</li><li>Save as <b>CSV</b>, then <a href="#contacts">upload your completed file below</a> and click <b>Import contacts</b>.</li></ol><p class="muted">Up to 10,000 contacts / 1 MB per file. Remove the example contacts before importing. Duplicate and invalid numbers are skipped.</p></section><?php endif; ?>
<section class="comm-card"><div class="comm-head"><div><h2>Audiences already in your app</h2><p class="muted">Choose a source to see the contacts available for this channel. Records stay in their original modules.</p></div><a class="btn secondary" href="#contacts">Import a list</a></div><p class="muted">Customer, client and patient contact details come from the main customer records. Invoices and appointments link to these records and are not counted as new people. A saved contact is not automatically a newsletter subscriber.</p></section>
<div class="comm-grid"><?php foreach($sources as $source): ?><article class="comm-card"><span class="comm-badge off"><?= $h($source['group']); ?></span><h3 style="margin-top:14px"><?= $h($source['name']); ?></h3><p class="muted"><?= $h($source['description']); ?></p><?php if($source['status']!==null): ?><span class="muted"><?= $h($source['status']); ?></span><?php else: ?><div class="metric"><?= number_format($source['eligible']); ?></div><p class="muted">eligible <?= $channel==='sms'?'phone numbers':'email recipients'; ?> · <?= number_format($source['records']); ?> source records</p><a href="<?= $h($workspace_url('audience',array('audience'=>$source['key']))); ?>">View this audience →</a><?php endif; ?></article><?php endforeach; ?></div>
<section class="comm-card" id="audience-lists"><div class="comm-head"><div><h2>Your <?= $channel==='sms'?'SMS':'email'; ?> audience lists</h2><p class="muted">Group the contacts you import, then pick the same group again for a campaign or an automation.</p></div><details><summary>New list</summary><?= form_open('communications/list_action'); ?><input type="hidden" name="action" value="create"><input type="hidden" name="channel" value="<?= $h($channel); ?>"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><label>Name<input name="name" maxlength="80" required placeholder="VIP customers"></label><label>Note (optional)<input name="note" maxlength="120" placeholder="Who this list is for"></label><button class="btn">Create list</button><?= form_close(); ?></details></div>
<div class="comm-grid"><?php foreach($lists as $list): $listUrl=$workspace_url('audience',array('audience'=>$list['key'])); ?><article class="comm-card"><span class="comm-badge ok"><?= number_format((int)$list['contact_count']); ?> contacts</span><h3 style="margin-top:14px"><?= $h($list['name']); ?></h3><?php if($list['note']!==''): ?><p class="muted"><?= $h($list['note']); ?></p><?php endif; ?><p><a href="<?= $h($listUrl); ?>">View these contacts →</a></p><details><summary>Rename or remove</summary><?= form_open('communications/list_action'); ?><input type="hidden" name="channel" value="<?= $h($channel); ?>"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><input type="hidden" name="list_id" value="<?= (int)$list['id']; ?>"><input type="hidden" name="action" value="rename"><label>Name<input name="name" maxlength="80" required value="<?= $h($list['name']); ?>"></label><label>Note (optional)<input name="note" maxlength="120" value="<?= $h($list['note']); ?>"></label><button class="btn">Save changes</button><?= form_close(); ?><?= form_open('communications/list_action'); ?><input type="hidden" name="channel" value="<?= $h($channel); ?>"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><input type="hidden" name="list_id" value="<?= (int)$list['id']; ?>"><input type="hidden" name="action" value="delete"><button class="btn secondary" type="button" data-list-remove="<?= $h($list['name']); ?>">Remove list</button><?= form_close(); ?><p class="muted">Removing a list keeps the contacts themselves.</p></details></article><?php endforeach; ?></div>
<?php if(!$lists): ?><p class="empty">No lists yet. Import contacts and choose “+ New audience list…” in the import box below.</p><?php endif; ?>
<?php if($listCap>0): ?><p class="muted">You can keep up to <?= (int)$listCap; ?> <?= $channel==='sms'?'SMS':'email'; ?> lists<?= $lists?', with '.max(0,$listCap-count($lists)).' still available.':''; ?></p><?php endif; ?></section>
<?php if($preview): ?><section class="comm-card"><div class="comm-head"><div><h2><?= $h($preview['name']); ?></h2><p class="muted"><?= $h($preview['description']); ?></p></div><?php if($preview['status']===null): ?><a class="btn" href="<?= $h($workspace_url('compose',array('audience'=>$preview['key']))); ?>">Create campaign</a><?php endif; ?></div><?php if($preview['status']!==null): ?><p class="notice"><?= $h($preview['status']); ?></p><?php else: ?><div class="comm-toolbar"><span class="comm-badge"><?= number_format($preview['eligible']); ?> eligible</span><span class="muted"><?= number_format($preview['invalid']); ?> missing / invalid · <?= number_format($preview['duplicates']); ?> duplicates · <?= number_format($preview['opted_out']); ?> opted out</span></div><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Name</th><th><?= $channel==='sms'?'Phone number':'Email address'; ?></th><th>Source</th></tr></thead><tbody><?php foreach(array_slice($preview['contacts'],0,50) as $contact): ?><tr><td><?= $h($contact->name?:'—'); ?></td><td><?= $h($contact->recipient); ?></td><td><?= $h($contact->source_name??$preview['name']); ?></td></tr><?php endforeach; ?></tbody></table></div><p class="muted">Showing up to 50 eligible recipients. The campaign uses the full selected audience, not only this preview.</p><?php if(!$preview['contacts']): ?><p class="empty">No eligible contacts for this channel in this source.</p><?php endif;endif; ?></section><?php endif; ?>
